        if not api or not callable(getattr(api, "get_item", None)):
            # 无法证明目录之前不存在，则绝不能在失败后删除。
            txn["unsafe"] = True
            return

        current = protected if protected != "/" else ""
        for part in relative.split("/"):
            current = self._cloud_path_v11218((current.rstrip("/") + "/" + part) or "/")
