gying_recall_guard_v1125:
"""v1.12.5 迅雷召回最终可用性门禁。

只修正“搜索结果是否足以停止关键词降级”的集数判定，不复制媒体身份规则：
- 标题/别名/年份/季号继续统一调用 v1.11.1 MediaIdentityGuard 的运行时权威；
- TV 候选若显式标出了集号且与 MoviePilot 当前真实缺集完全不相交，视为不可用；
- 未标集号的整季包/合集仍保留为潜在可用候选，避免为了扩大关键词无意义增加请求；
- 关键词降级后，把本轮真正成功请求过的各级详情结果合并回原关键词 120 秒缓存，
  即使没有可用迅雷，后续 Magnet 也能复用已经付出的 downurl 请求；SearchBundle 使用
  最老的有效成员请求时间作为 TTL，不把旧严格查询借较新的宽搜结果延寿；
- 精准迅雷搜索保持原 GYING 节点故障切换：单节点搜索异常最多换 3 次节点，但账号/验证码
  或 viewing_session 已确认全节点不可用时立即停止，不能把认证故障放大成重试风暴；
- 某一级迅雷候选通过预筛但实际秒传失败时，才继续下一档关键词；同一 share+passcode
  本轮不重复尝试，但同一分享在宽关键词补出了新的提取码时允许重试；
- 若某一级搜索本身失败（节点/登录/HTTP 且节点切换仍失败），立即停止继续放宽；
- Magnet/ED2K 以“实际执行结果”为准：严格候选存在但因旧集、错媒体或历史失败未产生 action 时，
  才逐级补查宽关键词；若严格搜索本身没有成功缓存则不继续放宽；
- 真正的媒体身份与文件级缺集校验仍由现有迅雷 JSON / Episode Planner 最终确认。

v1.12.19 开发阶段只增加安全排序与来源质量学习：
- 固定来源层级永远先于学习分，外部候选仍保持 Magnet > ED2K；
- 排序只作用于已召回候选，不改变 MediaIdentity / library missing / reservation / source claim / 物理文件硬栅栏；
- 来源质量只统计插件自身来源从非终态进入 completed / failed 的真实终态，不把 retry/waiting 当失败；
- 学习分使用带先验的有界分数，只在同一来源层级和安全覆盖特征之后作为 tie-break；
- 通过线程本地上下文把 subscribe/uncovered 只读传给搜索排序，不重写既有 dispatch 执行链。

本层是标准 cooperative mixin，不继承旧 Hardening；运行时显式放在 Hardening 前面。
"""
from __future__ import annotations

import threading
import time
from typing import Any, Dict, Iterable, List, Set, Tuple

from .episode_resolver_v190 import AUTO_SELECT_CONFIDENCE, reliable_episode_set, resolve_episode
from .gying_hardening_v193 import gying_keyword_variants


_CANDIDATE_QUALITY_DATA_KEY_V11219 = "candidate_quality_v11219"
_CANDIDATE_QUALITY_CACHE_TTL_V11219 = 30.0
_EXTERNAL_SOURCE_TIER_V11219 = {"magnet": 0, "ed2k": 1}
_TERMINAL_SOURCE_OUTCOME_V11219 = {"completed": True, "failed": False}


def _nonnegative_int_v11219(value: Any) -> int:
    try:
        return max(0, int(value or 0))
    except (TypeError, ValueError):
        return 0


def _nonnegative_float_v11219(value: Any) -> float:
    try:
        return max(0.0, float(value or 0))
    except (TypeError, ValueError):
        return 0.0


def candidate_quality_score_v11219(stats: Dict[str, Any]) -> int:
    """Beta(2,2) 平滑后的有界质量分；无样本严格为 0。"""
    success = _nonnegative_int_v11219((stats or {}).get("success"))
    failure = _nonnegative_int_v11219((stats or {}).get("failure"))
    if success + failure <= 0:
        return 0
    posterior = (success + 2.0) / (success + failure + 4.0)
    return max(-100, min(100, int(round((posterior - 0.5) * 200.0))))


def candidate_rank_key_v11219(
    source_type: str,
    eligible: bool,
    coverage_penalty: int,
    extra_episode_count: int,
    hit_episode_count: int,
    quality_score: int,
    candidate_rank: int,
    original_index: int,
) -> Tuple[int, int, int, int, int, int, int, int]:
    """固定来源层级是最高优先维度，学习分永远不能跨层级翻盘。"""
    source_tier = _EXTERNAL_SOURCE_TIER_V11219.get(str(source_type or "").strip().lower(), 99)
    return (
        source_tier,
        0 if eligible else 1,
        max(0, int(coverage_penalty or 0)),
        max(0, int(extra_episode_count or 0)),
        -max(0, int(hit_episode_count or 0)),
        -max(-100, min(100, int(quality_score or 0))),
        max(0, int(candidate_rank or 0)),
        max(0, int(original_index or 0)),
    )


class GuangYaGyingRecallGuardV1125Mixin:
    """最终迅雷召回门禁：预筛、真实执行失败后的渐进降级、SearchBundle 复用。"""

    build_id = "20260904-r51"

    def _recall_retry_local_v1125(self):
        local = getattr(self, "_gying_recall_retry_local_v1125", None)
        if local is None:
            local = threading.local()
            self._gying_recall_retry_local_v1125 = local
        return local

    @staticmethod
    def _candidate_episode_hint_v1125(subscribe: Any, row: Dict[str, Any]) -> Set[int]:
        label = " ".join(
            str(value or "").strip()
            for value in (row.get("name"), row.get("search_title"))
            if str(value or "").strip()
        )
        if not label:
            return set()
        try:
            parsed = resolve_episode(label, season_hint=getattr(subscribe, "season", None))
            return set(reliable_episode_set(parsed, AUTO_SELECT_CONFIDENCE))
        except Exception:
            return set()

    def _candidate_can_cover_missing_v1125(
        self,
        subscribe: Any,
        row: Dict[str, Any],
        missing: Set[int],
    ) -> bool:
        """显式旧集直接排除；无集号候选保留给分享文件级 planner 最终确认。"""
        if self._is_movie_subscription(subscribe) or not missing:
            return True
        explicit = self._candidate_episode_hint_v1125(subscribe, row)
        return not explicit or bool(explicit.intersection(missing))

    def _promote_search_bundle_v1125(
        self,
        primary: str,
        variants: Iterable[str],
        subscribe: Any = None,
    ) -> None:
        """只合并仍在 TTL 内的真实成功缓存；任何成员都不能因 bundle 合并被延长寿命。"""
        cache = getattr(self, "_gying_search_cache", None)
        primary = " ".join(str(primary or "").split())
        if not isinstance(cache, dict) or not primary:
            return
        cache_key_getter = getattr(self, "_gying_search_cache_key_v11223", None)

        def scoped_key(value: str) -> str:
            return cache_key_getter(value, subscribe) if callable(cache_key_getter) else value

        valid_variants: List[str] = []
        merged: List[Dict[str, Any]] = []
        seen = set()
        final_state: Dict[str, Any] = {}
        oldest_ts = 0.0
        now = time.time()
        ttl = 120.0
        for raw_variant in variants or []:
            variant = " ".join(str(raw_variant or "").split())
            if not variant or variant in valid_variants:
                continue
            entry = dict(cache.get(scoped_key(variant)) or {})
            if not entry:
                continue
            state = entry.get("state")
            if isinstance(state, dict) and state.get("success") is False:
                continue
            try:
                entry_ts = float(entry.get("ts") or 0)
            except (TypeError, ValueError):
                entry_ts = 0.0
            # Protocol 的普通读取也只接受 120 秒缓存；bundle 不能把已经过期的成员重新复活。
            if entry_ts <= 0 or now - entry_ts >= ttl:
                continue
            valid_variants.append(variant)
            oldest_ts = entry_ts if oldest_ts <= 0 else min(oldest_ts, entry_ts)
            if isinstance(state, dict):
                final_state = dict(state)
            for raw_row in entry.get("rows") or []:
                if not isinstance(raw_row, dict):
                    continue
                row = dict(raw_row)
                url = str(row.get("url") or row.get("uri") or "").strip()
                passcode = str(row.get("passcode") or "").strip()
                key = (url, passcode)
                if not url or key in seen:
                    continue
                seen.add(key)
                merged.append(row)

        if not valid_variants or oldest_ts <= 0:
            return
        effective = valid_variants[-1]
        final_state.update({
            "success": True,
            "query_fallback": effective if effective != primary else final_state.get("query_fallback"),
            "search_bundle_v1125": True,
            "bundle_variants": valid_variants,
            "bundle_resources": len(merged),
        })
        cache[scoped_key(primary)] = {
            # 取最老有效成员的真实请求时间：所有合并行都会在各自原 TTL 之前一起失效。
            "ts": oldest_ts,
            "rows": merged[:800],
            "state": final_state,
        }

    def _gying_xunlei_precise_variant_v1125(self, keyword: str):
        """给精准搜索补回 Failover 语义；认证失败和全节点不可用不做无意义重试。"""
        if not bool(getattr(self, "_viewing_auto_switch", True)):
            return super()._gying_xunlei_precise_variant_v1125(keyword)

        attempted_nodes = set()
        last_candidates: List[Dict[str, Any]] = []
        last_state: Dict[str, Any] = {"success": False, "message": "观影迅雷搜索失败"}
        for _attempt in range(3):
            candidates, state = super()._gying_xunlei_precise_variant_v1125(keyword)
            last_candidates, last_state = list(candidates or []), dict(state or {})
            if last_state.get("success"):
                return last_candidates, last_state

            mode = str(last_state.get("mode") or "").lower()
            message = str(last_state.get("message") or "")
            bad_credentials = getattr(self, "_gying_bad_credentials", None)
            if mode in {"disabled", "unavailable"} or (
                callable(bad_credentials) and bool(bad_credentials(message))
            ):
                return last_candidates, last_state

            failed_node = str(last_state.get("node") or "").strip()
            if not failed_node or failed_node in attempted_nodes:
                return last_candidates, last_state
            attempted_nodes.add(failed_node)

            # Hardening 已把当前节点标记为 search_error；这里清掉 active 粘性并清理本关键词缓存，
            # 下一轮 _viewing_session 会按 Failover 健康顺序选择其它节点。
            try:
                store = dict(self._gying_state() or {})
                if str(store.get("active_node") or "") == failed_node:
                    store["active_node"] = ""
                    self._save_gying_state(store)
            except Exception:
                pass
            cache = getattr(self, "_gying_search_cache", None)
            if isinstance(cache, dict):
                clean_keyword = " ".join(str(keyword or "").split())
                cache_key_getter = getattr(self, "_gying_search_cache_key_v11223", None)
                cache_key = cache_key_getter(clean_keyword) if callable(cache_key_getter) else clean_keyword
                cache.pop(cache_key, None)
        return last_candidates, last_state

    def _search_viewing_xunlei(self, keyword: str):
        """只有当前媒体且可能覆盖当前缺集的迅雷候选，才能停止当前一档搜索。"""
        all_variants = gying_keyword_variants(keyword)
        if not all_variants:
            return super()._search_viewing_xunlei(keyword)

        retry_local = self._recall_retry_local_v1125()
        try:
            start_index = max(0, int(getattr(retry_local, "start_index", 0) or 0))
        except (TypeError, ValueError):
            start_index = 0
        start_index = min(start_index, len(all_variants))
        variants = all_variants[start_index:]
        if not variants:
            return [], {
                "provider": "viewing_xunlei",
                "success": True,
                "message": "观影迅雷关键词层级已全部尝试",
                "searched_variants": all_variants,
            }

        context = getattr(self, "_gying_xunlei_context_v1125", None)
        subscribe = getattr(context, "subscribe", None) if context is not None else None
        seen_identities = set(getattr(retry_local, "seen_identities", set()) or set())
        last_state: Dict[str, Any] = {
            "provider": "viewing_xunlei",
            "success": False,
            "message": "观影迅雷搜索失败",
        }
        successful: List[str] = []
        for relative_index, variant in enumerate(variants):
            absolute_index = start_index + relative_index
            retry_local.last_attempted_index = absolute_index
            candidates, state = self._gying_xunlei_precise_variant_v1125(variant)
            last_state = dict(state or {})
            if not last_state.get("success"):
                retry_local.stop_after_failure = True
                bundle_variants = [all_variants[0], *successful] if start_index else successful
                if len(set(bundle_variants)) > 1:
                    self._promote_search_bundle_v1125(all_variants[0], bundle_variants)
                return candidates, last_state
            successful.append(variant)

            matched: List[Dict[str, Any]] = []
            for row in list(candidates or []):
                identity = str((row or {}).get("share_id") or (row or {}).get("identity") or "").strip()
                passcode = str((row or {}).get("passcode") or "").strip()
                retry_key = (identity, passcode)
                if identity and retry_key in seen_identities:
                    continue
                matched.append(row)

            missing: Set[int] = set()
            if subscribe is not None:
                # 不在这里重写标题/年份/季号规则；运行时 self 会优先解析到
                # GuangYaMediaIdentityGuardV1111Mixin._provider_candidate_matches。
