        if self._daily_summary:
            try:
                summary_trigger = CronTrigger.from_crontab(self._summary_cron)
            except Exception:
                self._plugin_log("WARNING", "【光鸭转存助手】【日报】Cron 配置无效，回退到每天 22:30")
